router11.patch("/admin/platform-settings", async (req, res) => {
  try {
    if (!await requireAdmin2(req, res)) return;
    const { publicVisibility, guestLimit, primaryColor, accentColor, fontFamily, platformName, logoUrl, showAdventureGamesHome, showSpaceRaceGamesHome, showFlagsGame, showColorGame, showMemoryGame, showMultiplyGame, showScrambleGame, showTugGame, showCapitalsGame, proAiForAll, presentationsProForAll, presentationLimits, showQuranSection, showGeneralCertificates, showMaraqui, classroomEnabled, classroomAllowedEmails } = req.body;
    const update = {};
    if (publicVisibility !== void 0) {
      if (!["all", "none", "selective"].includes(publicVisibility)) {
        return res.status(400).json({ message: "publicVisibility \u063A\u064A\u0631 \u0635\u0627\u0644\u062D" });
      }
      update.publicVisibility = publicVisibility;
    }
    if (guestLimit !== void 0) {
      const limit2 = Number(guestLimit);
      if (!Number.isInteger(limit2) || limit2 < 0 || limit2 > 9999) {
        return res.status(400).json({ message: "guestLimit \u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0631\u0642\u0645\u0627\u064B \u0628\u064A\u0646 0 \u06489999" });
      }
      update.guestLimit = limit2;
    }
    if (primaryColor !== void 0) update.primaryColor = primaryColor || null;
    if (accentColor !== void 0) update.accentColor = accentColor || null;
    if (fontFamily !== void 0) update.fontFamily = fontFamily || null;
    if (platformName !== void 0) update.platformName = platformName || null;
    if (logoUrl !== void 0) update.logoUrl = logoUrl || null;
    if (showAdventureGamesHome !== void 0) update.showAdventureGamesHome = Boolean(showAdventureGamesHome);
    if (showSpaceRaceGamesHome !== void 0) update.showSpaceRaceGamesHome = Boolean(showSpaceRaceGamesHome);
    if (showFlagsGame !== void 0) update.showFlagsGame = Boolean(showFlagsGame);
    if (showColorGame !== void 0) update.showColorGame = Boolean(showColorGame);
    if (showMemoryGame !== void 0) update.showMemoryGame = Boolean(showMemoryGame);
    if (showMultiplyGame !== void 0) update.showMultiplyGame = Boolean(showMultiplyGame);
    if (showScrambleGame !== void 0) update.showScrambleGame = Boolean(showScrambleGame);
    if (showTugGame !== void 0) update.showTugGame = Boolean(showTugGame);
    if (showCapitalsGame !== void 0) update.showCapitalsGame = Boolean(showCapitalsGame);
    if (proAiForAll !== void 0) update.proAiForAll = Boolean(proAiForAll);
    if (presentationsProForAll !== void 0) update.presentationsProForAll = Boolean(presentationsProForAll);
    if (presentationLimits !== void 0) {
      const parsed = PresentationLimitsSchema.safeParse(presentationLimits);
      if (!parsed.success) {
        return res.status(400).json({ message: "presentationLimits \u063A\u064A\u0631 \u0635\u0627\u0644\u062D" });
      }
      update.presentationLimits = parsed.data;
    }
    if (showQuranSection !== void 0) update.showQuranSection = Boolean(showQuranSection);
    if (showGeneralCertificates !== void 0) update.showGeneralCertificates = Boolean(showGeneralCertificates);
    if (showMaraqui !== void 0) update.showMaraqui = Boolean(showMaraqui);
    if (classroomEnabled !== void 0) update.classroomEnabled = Boolean(classroomEnabled);
    if (classroomAllowedEmails !== void 0) {
      if (!Array.isArray(classroomAllowedEmails)) {
        return res.status(400).json({ message: "classroomAllowedEmails \u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0642\u0627\u0626\u0645\u0629" });
      }
      const cleaned = Array.from(
        new Set(
          classroomAllowedEmails.map((e2) => typeof e2 === "string" ? e2.trim().toLowerCase() : "").filter((e2) => e2.length > 0 && e2.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e2))
        )
      ).slice(0, 500);
      update.classroomAllowedEmails = cleaned;
    }
    if (Object.keys(update).length === 0) {
      return res.status(400).json({ message: "\u0644\u0627 \u062A\u0648\u062C\u062F \u062D\u0642\u0648\u0644 \u0644\u0644\u062A\u062D\u062F\u064A\u062B" });
    }
    const current = await getPlatformSettings();
    await db.insert(platformSettingsTable).values({ id: 1, publicVisibility: current.publicVisibility, guestLimit: current.guestLimit, ...update }).onConflictDoUpdate({ target: platformSettingsTable.id, set: update });
    const updated = await getPlatformSettings();
    res.json(updated);
  } catch (err) {
    req.log.error(err, "Failed to update platform settings");
    res.status(500).json({ message: "\u062D\u062F\u062B \u062E\u0637\u0623" });
  }
});
