function buildDetailedResults(game) {
  return Array.from(game.players.values()).filter((p) => !p.isBot).sort((a, b) => b.score - a.score).map((p, idx) => {
    const answersArr = [];
    for (const [qIdx, ans] of p.answers.entries()) {
      const q = game.questions[qIdx];
      answersArr.push({
        questionIndex: qIdx,
        questionText: q?.text || `\u0633\u0624\u0627\u0644 ${qIdx + 1}`,
        answer: ans.answer,
        correct: ans.correct,
        points: ans.points,
        time: ans.time
      });
    }
    return {
      rank: idx + 1,
      name: p.name,
      avatar: p.avatar,
      score: p.score,
      totalCorrect: p.totalCorrect,
      totalQuestions: game.questions.length,
      teamName: p.teamName,
      answers: answersArr
    };
  });
}
