            queueBotTimers.delete(socket.id);
            const stillQueued = matchQueue.get(gameId);
            if (!stillQueued || stillQueued.socketId !== socket.id) return;
            matchQueue.delete(gameId);
            socketToQueue.delete(socket.id);
