// src/seedMillionBank.ts
init_src();
import { execSync as execSync2 } from "child_process";
import path3 from "path";
import { fileURLToPath as fileURLToPath2 } from "url";
import fs3 from "fs";
var __dirname3 = path3.dirname(fileURLToPath2(import.meta.url));
async function getBankCount() {
  const { rows } = await pool.query("SELECT COUNT(*)::int AS cnt FROM million_bank_questions");
  return rows[0]?.cnt ?? 0;
}
async function fixCategoryConstraint() {
  await pool.query(`
    ALTER TABLE million_bank_questions
      DROP CONSTRAINT IF EXISTS million_bank_category_check;
    ALTER TABLE million_bank_questions
      ADD CONSTRAINT million_bank_category_check CHECK (
        category = ANY (ARRAY[
          'culture', 'religion', 'language', 'inventions', 'countries',
          'technology', 'science', 'geography',
          'history', 'sports', 'mathematics', 'art', 'space', 'economics',
          'animals', 'food', 'cinema', 'medicine', 'plants', 'nature',
          'politics', 'energy', 'literature'
        ])
      );
  `);
}
function findRepoRoot() {
  const candidates = [
    path3.resolve(__dirname3, "../../.."),
    path3.resolve(__dirname3, "../../../.."),
    path3.resolve(process.cwd(), "../.."),
    process.cwd()
  ];
  for (const dir of candidates) {
    if (fs3.existsSync(path3.join(dir, "scripts", "seed-million-bank.mjs"))) {
      return dir;
    }
  }
  return process.cwd();
}
async function seedMillionBankIfEmpty() {
  try {
    const count2 = await getBankCount();
    if (count2 > 0) return;
    console.log("[seedMillionBank] Bank is empty \u2014 starting seed...");
    await fixCategoryConstraint();
    console.log("[seedMillionBank] CHECK constraint updated.");
    const repoRoot = findRepoRoot();
    const env2 = { ...process.env };
    const seedScript = path3.join(repoRoot, "scripts", "seed-million-bank.mjs");
    if (fs3.existsSync(seedScript)) {
      console.log("[seedMillionBank] Running seed-million-bank.mjs ...");
      execSync2(`node "${seedScript}"`, { env: env2, stdio: "inherit", cwd: repoRoot });
    } else {
      console.warn("[seedMillionBank] seed-million-bank.mjs not found at", seedScript);
    }
    const importScript = path3.join(repoRoot, "scripts", "import-500-questions.mjs");
    const questionsFile = path3.join(repoRoot, "attached_assets", "Pasted--500-4--1776123641404_1776123641405.txt");
    if (fs3.existsSync(importScript) && fs3.existsSync(questionsFile)) {
      console.log("[seedMillionBank] Running import-500-questions.mjs ...");
      execSync2(`node "${importScript}"`, { env: env2, stdio: "inherit", cwd: repoRoot });
    } else {
      console.warn("[seedMillionBank] import script or questions file not found \u2014 skipping 500-question import.");
    }
    const finalCount = await getBankCount();
    console.log(`[seedMillionBank] Done. Bank now has ${finalCount} questions.`);
  } catch (err) {
    console.error("[seedMillionBank] Seeding failed (non-fatal):", err);
  }
}

