var SEED_MARKER = "\u0639\u064E\u0645\u064E\u0651 \u064A\u064E\u062A\u064E\u0633\u064E\u0627\u0621\u064E\u0644\u064F\u0648\u0646\u064E";
async function seedIslamicIfNeeded() {
  try {
    const existingMarker = await db.select({ id: islamicQuestionsTable.id }).from(islamicQuestionsTable).where(like(islamicQuestionsTable.questionText, `%${SEED_MARKER}%`)).limit(1);
    if (existingMarker.length > 0) return;
    logger.info("[seedIslamic] applying canonical General Quizzes seed\u2026");
    let section = (await db.select().from(islamicSectionsTable).where(eq(islamicSectionsTable.name, SECTION_NAME)).limit(1))[0];
    if (!section) {
      [section] = await db.insert(islamicSectionsTable).values({
        name: SECTION_NAME,
        description: SECTION_DESC,
        isVisible: false,
        order: 1
      }).returning();
    } else {
      await db.update(islamicSectionsTable).set({ description: SECTION_DESC, isVisible: false, order: 1 }).where(eq(islamicSectionsTable.id, section.id));
    }
    for (const cat of CATEGORIES) {
      const existing = await db.select().from(islamicCategoriesTable).where(
        and(
          eq(islamicCategoriesTable.sectionId, section.id),
          eq(islamicCategoriesTable.order, cat.order)
        )
      ).limit(1);
      let catRow = existing[0];
      if (!catRow) {
        [catRow] = await db.insert(islamicCategoriesTable).values({
          sectionId: section.id,
          name: cat.name,
          description: cat.description,
          level: cat.level,
          order: cat.order,
          isVisible: true
        }).returning();
      } else {
        await db.update(islamicCategoriesTable).set({
          name: cat.name,
          description: cat.description,
          level: cat.level,
          isVisible: true
        }).where(eq(islamicCategoriesTable.id, catRow.id));
      }
      await db.delete(islamicQuestionsTable).where(eq(islamicQuestionsTable.categoryId, catRow.id));
      await db.insert(islamicQuestionsTable).values(
        cat.questions.map((q) => ({
          categoryId: catRow.id,
          questionText: q.q,
          optionA: q.a,
          optionB: q.b,
          optionC: q.c,
          optionD: q.d,
          correctAnswer: q.correct,
          difficulty: q.difficulty
        }))
      );
    }
    logger.info(
      { sectionId: section.id, categories: CATEGORIES.length },
      "[seedIslamic] General Quizzes seed applied"
    );
  } catch (err) {
    logger.error({ err }, "[seedIslamic] failed");
  }
}

