var CLEANUP_INTERVAL_MS2 = 24 * 60 * 60 * 1e3;
var STALE_AFTER_DAYS = 7;
async function cleanupPasswordResetTokens() {
  const cutoff = new Date(Date.now() - STALE_AFTER_DAYS * 24 * 60 * 60 * 1e3);
  try {
    const deleted = await db.delete(passwordResetTokensTable).where(
      or(
        lt(passwordResetTokensTable.expiresAt, cutoff),
        and(
          isNotNull(passwordResetTokensTable.usedAt),
          lt(passwordResetTokensTable.usedAt, cutoff)
        )
      )
    ).returning({ id: passwordResetTokensTable.id });
    if (deleted.length > 0) {
      logger.info(
        { count: deleted.length, cutoff: cutoff.toISOString() },
        "Pruned stale password reset tokens"
      );
    }
    return deleted.length;
  } catch (err) {
    logger.error({ err }, "Failed to prune password reset tokens");
    return 0;
  }
}
function startPasswordResetCleanupJob() {
  void cleanupPasswordResetTokens();
  const handle = setInterval(() => {
    void cleanupPasswordResetTokens();
  }, CLEANUP_INTERVAL_MS2);
  if (typeof handle.unref === "function") handle.unref();
  return handle;
}

